% Calculate the number of working days for parental leave

start_date = datetime(2022, 4,24);
end_date = datetime(2022,9,9);

% Calculate the total number of days between the start and end dates
total_days = end_date - start_date;

% Calculate the number of weekend days (Saturdays)
weekend_days = floor(total_days / 7) * 2;
remainder_days = mod(total_days,7);
weekend_days = floor(remainder_days / 2) * 2;
remainder_days = mod(remainder_days,2);

% Add back the weekend days
if mod(remainder_days,2) == 1
    weekend_days = weekend_days + 1;
end
else
    weekend_days = weekend_days;
end

% Calculate the number of working days
working_days = total_days - weekend_days;

% Display the result
fprintf('Total working days for parental leave: %d\n', working_days);
